        password=os.environ.get("EXPERIMENT_DB_PASSWORD", "sdl_secure_2025"),
    )


# ============================================================================
# HELPER FUNCTIONS
# ============================================================================


def parse_numeric(value):
    """Extract a numeric value from a string like '25 °C' or '100 mM'.

    Call this ONLY for a single-valued field eLabFTW types as a number. On a text field
    it is destructive - '20 mM NaAc' becomes 20.0 and the buffer identity is gone - and
    on a delimited list it keeps only the first element. When in doubt, store the
    original string unchanged.
    """

    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        # Replace comma decimal with dot if it looks like a single number
        # but DO NOT treat comma as decimal if there are multiple tokens
        import re

        match = re.search(r"[-+]?\d*[,\.]?\d+", text)
        if match:
            num_str = match.group(0).replace(",", ".")
            try:
                return float(num_str)
            except ValueError:
                return None
    return None


def parse_field(value, field_type=None):
    """Route an eLabFTW value by what it IS, not by which parameter it came from.

    Any field may arrive as a delimited list, so the delimiter check comes first.
    """
    if value is None or value == "":
        return None
    if isinstance(value, (list, int, float)):
        return value
    text = str(value).strip()
    # a list if a delimiter separates more than one token; "1,5" (decimal comma) is one
    for sep in (";", ","):
        parts = [p.strip() for p in text.split(sep) if p.strip()]
        if len(parts) > 1:
            # Check if this is actually a mistakenly split decimal number like "1,5"
            if sep == "," and len(parts) == 2:
                # Try to parse as a single float using comma as decimal
                try:
                    as_float = float(text.replace(",", "."))
                    return as_float if field_type == "number" else text
                except ValueError:
                    pass
            # Real list: convert to floats if all parts numeric, else keep strings
            all_numeric = True
            nums = []
            for p in parts:
                try:
                    nums.append(float(p.replace(",", ".")))
                except ValueError:
                    all_numeric = False
                    break
            if all_numeric and field_type == "number":
                return nums
            return parts
    if field_type == "number":
        num = parse_numeric(text)
        return num if num is not None else text
    return text  # text stays text


def find_experiment_json(elab_id):
    """Find experiment JSON file."""
    paths = [
        Path(f"../experiment_{elab_id}.json"),
        Path(f"../data/experiment_{elab_id}.json"),
    ]
    for p in paths:
        if p.exists():
            return p
    raise FileNotFoundError(f"Experiment JSON not found for {elab_id}")


def load_workflow():
    """Load workflow.json and extract lab_id."""
    workflow_path = Path("../workflow.json")
    if workflow_path.exists():
        with open(workflow_path) as f:
            data = json.load(f)
            return data, data.get("lab_id") or data.get("labId")
    return None, None


def extract_metadata(extra_fields):
    """Extract and map metadata from eLabFTW extra fields."""
    metadata = {}
    for elab_name, db_name in FIELD_MAPPING.items():
        if elab_name in extra_fields:
            field = extra_fields[elab_name]
            raw_value = field.get("value")
            field_type = field.get("type")
            # Use generic parser that respects potential lists and numeric typing
            parsed_value = parse_field(raw_value, field_type=field_type)
            metadata[db_name] = parsed_value
    return metadata


def list_folder_files(folder_path):
    """List files in a folder."""
    folder = Path(folder_path)
    if folder.exists():
        return [f.name for f in folder.iterdir() if f.is_file()]
    return []


def build_raw_data(elab_id):
    """Build raw_data JSONB structure."""
    data_folder = Path("../data")
    return {
        "folder_path": str(data_folder.resolve()),
        "files": list_folder_files(data_folder),
    }


def load_analysis_results(elab_id):
    """Load analysis_results_<ID>.json if available and return its dict.

    This mirrors the structure produced by the AKTA analysis script.
    """
    results_folder = Path("../results")
    json_path = results_folder / f"analysis_results_{elab_id}.json"
    if not json_path.exists():
        return None
    try:
        with open(json_path, "r") as f:
            return json.load(f)
    except Exception:
        return None


def build_results(elab_id):
    """Build results JSONB structure from analysis outputs.

    It aggregates file listings from ../results and ../analysis, and pulls key
    metrics from analysis_results_<ID>.json if present.
    """
    timestamp = datetime.now(timezone.utc).isoformat()

    results_root = Path("../results")
    analysis_root = Path("../analysis")

    results_files = list_folder_files(results_root)
    analysis_files = list_folder_files(analysis_root)

    analysis_json = load_analysis_results(elab_id)

    # Default status
    analysis_status = "pending"
    num_peaks = None
    data_files = {}
    plots = {}

    if analysis_json is None:
        analysis_status = "pending"
    else:
        # Map status
        status_str = str(analysis_json.get("status", "")).lower()
        if status_str == "success":
            analysis_status = "completed"
        elif status_str in {"failed", "error"}:
            analysis_status = "failed"
        else:
            analysis_status = "pending"

        # num_peaks lives under metadata in analysis script
        meta = analysis_json.get("metadata", {}) or {}
        if isinstance(meta.get("num_peaks"), int):
            num_peaks = meta.get("num_peaks")

        # data_outputs contains file paths
        data_outputs = analysis_json.get("data_outputs", {}) or {}
        if "akta_processed_csv" in data_outputs:
            data_files["akta_processed_csv"] = data_outputs["akta_processed_csv"]
        if "akta_peaks_csv" in data_outputs:
            data_files["akta_peaks_csv"] = data_outputs["akta_peaks_csv"]

        # path to analysis_results JSON itself
        data_files["analysis_results_json"] = str(
            results_root / f"analysis_results_{elab_id}.json"
        )

        # plots mapping
        plots_dict = analysis_json.get("plots", {}) or {}
        if "chromatogram_png" in plots_dict:
            plots["chromatogram_png"] = plots_dict["chromatogram_png"]

    summary = {}
    if num_peaks is not None:
        summary["num_peaks"] = num_peaks

    return {
        "analysis_status": analysis_status,
        "timestamp": timestamp,
        "summary": summary,
        "analysis_results_json": analysis_json,
        "data_files": data_files,
        "plots": plots,
        "results_folder": str(results_root.resolve()),
        "results_files": results_files,
        "analysis_folder": str(analysis_root.resolve()),
        "analysis_files": analysis_files,
    }


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""
    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
    """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id, data):
    """Insert or update experiment execution."""
    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
    """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    return cursor.fetchone()[0]


def main():
    parser = argparse.ArgumentParser(
        description=f"Commit {PROCESS_NAME} to database"
    )
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Don't commit, just show what would be done",
    )
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(f"Process schema updated: {PROCESS_NAME} (ID: {PROCESS_ID})")

        if args.init-schema-only if False else args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path) as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = (
            exp_data.get("metadata_decoded", {}).get("extra_fields", {})
        )
        workflow_json, lab_id = load_workflow()

        # Build metadata from extra fields
        metadata = extract_metadata(extra_fields)

        # If analysis_results exists, propagate num_peaks into metadata if present
        analysis_json = load_analysis_results(args.elab_id)
        if analysis_json is not None:
            meta_block = analysis_json.get("metadata", {}) or {}
            if "num_peaks" in meta_block and isinstance(
                meta_block["num_peaks"], int
            ):
                metadata["num_peaks"] = meta_block["num_peaks"]

        # Build data structures
        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": "completed",
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": metadata,
            "raw_data": build_raw_data(args.elab_id),
            "results": build_results(args.elab_id),
        }

        if args.dry_run:
            print("DRY RUN - Would insert:")
            print(json.dumps(data, indent=2, default=str))
            return 0

        # Commit to database
        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(
            f"Experiment {args.elab_id} committed successfully (DB ID: {exp_db_id})"
        )
        return 0

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if conn is not None:
            conn.rollback()
        return 1
    finally:
        if conn is not None:
            conn.close()


if __name__ == "__main__":
    sys.exit(main())
